html:
{% set company = frappe.get_doc("Company", doc.company) %}
{% set customer = frappe.get_doc("Customer", doc.customer) if doc.customer else None %}

{%- if doc.meta.is_submittable and doc.docstatus == 2 -%}
<div class="text-center" document-status="cancelled">
	<h4 style="margin-top: 20px;">ANNULÉE</h4>
</div>
{%- endif -%}
{%- if doc.meta.is_submittable and doc.docstatus == 0 -%}
<div class="text-center" document-status="draft">
	<h4 style="margin-top: 20px !important;">BROUILLON</h4>
</div>
{%- endif -%}

<style>
	.facture-maroc { font-size: 12px; color: #1a1a1a; }
	.facture-maroc h1 { font-size: 22px; margin: 0 0 4px 0; }
	.facture-maroc .header-table,
	.facture-maroc .parties-table,
	.facture-maroc .items-table,
	.facture-maroc .totals-table { width: 100%; border-collapse: collapse; }
	.facture-maroc .header-table td { vertical-align: top; padding: 4px 0; }
	.facture-maroc .parties-table td {
		vertical-align: top; width: 50%; padding: 8px 10px;
		border: 1px solid #d0d0d0;
	}
	.facture-maroc .block-label {
		font-size: 10px; text-transform: uppercase; letter-spacing: 0.5px;
		color: #666; margin-bottom: 4px;
	}
	.facture-maroc .items-table { margin-top: 12px; }
	.facture-maroc .items-table th {
		background: #f2f2f2; border: 1px solid #d0d0d0;
		padding: 6px 8px; text-align: left; font-size: 11px;
	}
	.facture-maroc .items-table td {
		border: 1px solid #d0d0d0; padding: 6px 8px; vertical-align: top;
	}
	.facture-maroc .totals-table { margin-top: 12px; margin-left: auto; width: 45%; }
	.facture-maroc .totals-table td { padding: 4px 8px; }
	.facture-maroc .totals-table .grand td {
		border-top: 2px solid #1a1a1a; font-weight: bold; font-size: 13px;
	}
	.facture-maroc .in-words { margin-top: 12px; font-style: italic; }
	.facture-maroc .legal-mentions {
		margin-top: 24px; padding-top: 8px; border-top: 1px solid #d0d0d0;
		font-size: 10px; color: #444; text-align: center;
	}
	.text-right { text-align: right; }
</style>

<div class="facture-maroc">
	<table class="header-table">
		<tr>
			<td>
				<h1>{{ company.company_name }}</h1>
				{% if doc.company_address_display %}{{ doc.company_address_display }}{% endif %}
			</td>
			<td class="text-right">
				<h1>FACTURE</h1>
				<div><strong>N° :</strong> {{ doc.name }}</div>
				<div><strong>Date :</strong> {{ frappe.format_date(doc.posting_date) }}</div>
				{% if doc.due_date %}<div><strong>Échéance :</strong> {{ frappe.format_date(doc.due_date) }}</div>{% endif %}
			</td>
		</tr>
	</table>

	<table class="parties-table" style="margin-top: 12px;">
		<tr>
			<td>
				<div class="block-label">Facturé à</div>
				<strong>{{ doc.customer_name }}</strong><br>
				{% if doc.address_display %}{{ doc.address_display }}<br>{% endif %}
				{% if customer and customer.custom_ice %}<strong>ICE :</strong> {{ customer.custom_ice }}{% endif %}
			</td>
			<td>
				<div class="block-label">Références</div>
				{% if doc.po_no %}<div><strong>Commande client :</strong> {{ doc.po_no }}</div>{% endif %}
				{% if doc.project %}<div><strong>Projet :</strong> {{ doc.project }}</div>{% endif %}
				<div><strong>Devise :</strong> {{ doc.currency }}</div>
				<div><strong>Conditions de paiement :</strong> {{ doc.payment_terms_template or "—" }}</div>
			</td>
		</tr>
	</table>

	<table class="items-table">
		<thead>
			<tr>
				<th style="width: 4%;">#</th>
				<th style="width: 44%;">Désignation</th>
				<th style="width: 8%;" class="text-right">Qté</th>
				<th style="width: 10%;">UdM</th>
				<th style="width: 16%;" class="text-right">P.U. HT</th>
				<th style="width: 18%;" class="text-right">Montant HT</th>
			</tr>
		</thead>
		<tbody>
			{% for row in doc.items %}
			<tr>
				<td>{{ loop.index }}</td>
				<td>
					<strong>{{ row.item_name or row.item_code }}</strong>
					{% if row.description and row.description != row.item_name %}<br>{{ row.description }}{% endif %}
				</td>
				<td class="text-right">{{ row.get_formatted("qty") }}</td>
				<td>{{ row.uom }}</td>
				<td class="text-right">{{ row.get_formatted("rate") }}</td>
				<td class="text-right">{{ row.get_formatted("amount") }}</td>
			</tr>
			{% endfor %}
		</tbody>
	</table>

	<table class="totals-table">
		<tr>
			<td>Total HT</td>
			<td class="text-right">{{ doc.get_formatted("total") }}</td>
		</tr>
		{% for tax in doc.taxes %}
		<tr>
			<td>{{ tax.description }}</td>
			<td class="text-right">{{ tax.get_formatted("tax_amount") }}</td>
		</tr>
		{% endfor %}
		{% if doc.discount_amount %}
		<tr>
			<td>Remise</td>
			<td class="text-right">- {{ doc.get_formatted("discount_amount") }}</td>
		</tr>
		{% endif %}
		<tr class="grand">
			<td>Total TTC</td>
			<td class="text-right">{{ doc.get_formatted("grand_total") }}</td>
		</tr>
	</table>

	{% if doc.in_words %}
	<div class="in-words">Arrêtée la présente facture à la somme de : <strong>{{ doc.in_words }}</strong></div>
	{% endif %}

	<div class="legal-mentions">
		{{ company.company_name }}
		{% if company.custom_ice %} — ICE : {{ company.custom_ice }}{% endif %}
		{% if company.custom_if %} — IF : {{ company.custom_if }}{% endif %}
		{% if company.custom_rc %} — RC : {{ company.custom_rc }}{% endif %}
		{% if company.custom_tp %} — TP : {{ company.custom_tp }}{% endif %}
		{% if company.custom_cnss %} — CNSS : {{ company.custom_cnss }}{% endif %}
	</div>
</div>

